ISSUE = re.compile(r"^[A-Z][A-Z0-9]+-\d+$")


def main_checkout(here: Path) -> Path | None:
    common = out(here, "rev-parse", "--path-format=absolute", "--git-common-dir")
    if not common or Path(common).name != ".git":
        return None
    return Path(common).parent


def base_branch(main: Path) -> str:
    """The branch every issue lands on: origin's default branch, else `init.defaultBranch`, else
    `main`. Never just whatever the main checkout has checked out: an owner on an experiment branch
    would have every issue land on (and be rebased onto) the experiment."""
    head = out(main, "symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD")
    if head.startswith("origin/"):
        return head[len("origin/") :]
    return out(main, "config", "init.defaultBranch") or "main"


def checked_out(main: Path) -> str:
    return out(main, "symbolic-ref", "--quiet", "--short", "HEAD")


def push_mode(main: Path) -> str:
    """`[agents] push` from the main checkout's `.luxarch.toml`, read as `unpushed-stop-guard` reads
    it (text, no tomllib on 3.9): "agent", "owner", or "" when undeclared."""
    try:
        text = (main / ".luxarch.toml").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""
    table = ""
    for raw in text.lstrip("﻿").splitlines():
        line = raw.split("#", 1)[0].strip()
        if line.startswith("["):
            table = line.strip("[] ")
            continue
        m = re.match(r'push\s*=\s*"(agent|owner)"\s*$', line)
        if table == "agents" and m:
            return m.group(1)
    return ""


def count(cwd: Path, spec: str) -> int:
    return int(out(cwd, "rev-list", "--count", spec) or "0")


def restore_hookspath(main: Path) -> bool:
    """Put `core.hooksPath` back to the relative `hooks` when it was rewritten to the absolute path of the
    main checkout's own tracked `hooks/`. Creating a worktree (Claude Code's EnterWorktree) writes that
    absolute path into the config every worktree shares, and luxlint's secret.githooks_wired then reds
    the repo. The relative value runs the same hooks: git resolves it from each worktree's root, and
    `hooks/` is tracked in every one. Any other value is left alone. True when it changed the config."""
    value = out(main, "config", "--get", "core.hooksPath")
    if not value or not Path(value).is_absolute():
        return False
    try:
        same = Path(value).resolve() == (main / "hooks").resolve()
    except OSError:
        return False
    if not same or not out(main, "ls-files", "hooks/"):
        return False
    return run(main, "config", "core.hooksPath", "hooks").returncode == 0


SITE_CONFIG = "Makefile.local"


def link_site_config(main: Path) -> list[str]:
    """Link the main checkout's ignored `Makefile.local` files (each at its own path) into every agent
    worktree that lacks one. That file is the machine's site config, the registry and the hosts the
    guard and image targets read, and a worktree is a checkout of tracked files only, so without it
    `guard-upgrade`, `status` and the gitleaks pre-commit skip or fail there. A link, not a copy: one
    file to keep current. A worktree's own file at that path is left alone, and `dirty` reads the link
    as a copy of main's file (a link to main's path, even once main's file is gone), so landing and
    pruning are unaffected. Returns the links made.

    A path is linked only where the worktree's own branch ignores it too (a link git would offer to
    commit holds this machine's absolute path), and only inside the worktree, never through a tracked
    symlink to a directory elsewhere."""
    found = out(
        main, "ls-files", "--others", "--ignored", "--exclude-standard", "--directory"
    )
    rels = [r for r in found.splitlines() if r.rsplit("/", 1)[-1] == SITE_CONFIG]
    made: list[str] = []
    for row in worktrees(main):
        wt = Path(row.get("worktree", ""))
        if not row.get("worktree") or wt.parent != main / ".claude" / "worktrees":
            continue
        try:
            root = wt.resolve()
        except OSError:
            continue
        for rel in rels:
            dst = wt / rel
            if dst.exists() or dst.is_symlink() or not (main / rel).is_file():
                continue
            try:
                parent = dst.parent.resolve()
            except OSError:
                continue
            if not parent.is_dir() or (parent != root and root not in parent.parents):
                continue
            # check-ignore refuses --literal-pathspecs (run's), so `./` keeps a leading `:` literal
            ignored = subprocess.run(
                ["git", "-C", str(wt), "check-ignore", "-q", "--", f"./{rel}"],
                capture_output=True,
                text=True,
                env=git_env(),
            )
            if ignored.returncode != 0:
                continue
            with contextlib.suppress(OSError):  # another session linked it first
                dst.symlink_to(main / rel)
                made.append(f"{wt.name}/{rel}")
    return made


def worktrees(main: Path) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    cur: dict[str, str] = {}
    for line in out(main, "worktree", "list", "--porcelain").splitlines() + [""]:
        if not line:
            if cur:
                rows.append(cur)
            cur = {}
            continue
        key, _, value = line.partition(" ")
        cur[key] = value or "1"
    return rows


# Directories a tool writes and rebuilds on its next run. An ignored file in one of these is not
# work; every worktree that ever ran a test or a linter has them, and counting them kept every
# worktree forever. A directory holding a `CACHEDIR.TAG` (the cache-directory standard,
# https://bford.info/cachedir/) says so itself, whatever the tool's name.
CACHE_DIRS = frozenset(
    {
        "__pycache__",
        ".pytest_cache",
        ".mypy_cache",
        ".ruff_cache",
        ".hypothesis",
        ".import_linter_cache",
        "node_modules",
        ".build",  # SwiftPM
        "DerivedData",  # Xcode
    }
)


# Files the emitted hooks themselves rewrite in whatever checkout a session works in: removing one
# loses nothing, and counting it kept every worktree a session had been in.
HOOK_FILES = frozenset({".claude/.hooks-heartbeat"})


def _regenerable(root: Path, rel: str) -> bool:
    if rel in HOOK_FILES:
        return True
    parts = rel.rstrip("/").split("/")
    if any(part in CACHE_DIRS for part in parts):
        return True
    return any(
        (root.joinpath(*parts[:i]) / "CACHEDIR.TAG").is_file()
        for i in range(1, len(parts) + 1)
    )


def _copy_of_main(path: Path, main: Path | None, rel: str) -> bool:
    """An ignored file byte-identical to the same path in the main checkout (Claude Code copies
    `.claude/settings.local.json` into every worktree it makes): removing it loses nothing. Only while
    main does NOT track that path (v5): an issue that stops tracking a committed `.env` leaves the
    worktree's ignored copy identical to main's TRACKED one, and landing deletes main's copy, so
    removing the worktree would delete the last one."""
    if main is None or main == path:
        return False
    a, b = path / rel, main / rel
    try:
        # a link `link_site_config` makes holds nothing of its own, target or not
        same = (a.is_symlink() and os.readlink(a) == str(b)) or (
            a.is_file() and b.is_file() and a.read_bytes() == b.read_bytes()
        )
    except OSError:
        return False
    return same and run(main, "ls-files", "--error-unmatch", "--", rel).returncode != 0


def blockers(path: Path, main: Path | None = None) -> list[str]:
    """Every file git does not hold: changed, untracked or IGNORED, whatever the repo's status config.
    `git worktree remove` deletes ignored files (a `.env`) and, under `status.showUntrackedFiles=no`,
    untracked ones; a file git does not hold is a file nothing can bring back. The exceptions are
    ignored files that are not work: one inside a tool's cache directory, which the tool rebuilds,
    and an exact copy of the main checkout's file at the same path. A submodule is read whatever
    `submodule.<name>.ignore` says (a commit or a change in it is a line here), and so are the files
    inside each checked-out one, ignored ones included, which the superproject's status never lists.
    A checkout git cannot read is a blocker: nothing shows what it holds."""
    r = run(
        path,
        "status",
        "--porcelain",
        "--untracked-files=all",
        "--ignored",
        "--ignore-submodules=none",
    )
    if r.returncode != 0:
        why = (r.stderr.strip().splitlines() or ["git status failed"])[0]
        return [f"?? ./ (git cannot read this checkout: {why})"]
    found: list[str] = []
    for line in r.stdout.splitlines():
        rel = line[3:]
        if not (
            line.startswith("!! ")
            and (_regenerable(path, rel) or _copy_of_main(path, main, rel))
        ):
            found.append(line)
    for rel, _ in gitlinks(path):
        if populated(path / rel):
            found += [f"{x[:3]}{rel}/{x[3:]}" for x in blockers(path / rel)]
    return found


def dirty(path: Path, main: Path | None = None) -> bool:
    return bool(blockers(path, main))


DOCKER_SECONDS = 20.0
# a docker that hangs (TimeoutExpired) or cannot be started
_DOCKER_ERRORS = (OSError, subprocess.SubprocessError)


def _docker(*args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["docker", *args],
        capture_output=True,
        text=True,
        stdin=subprocess.DEVNULL,
        timeout=DOCKER_SECONDS,
    )


def running_mounts() -> tuple[list[tuple[str, str]], str]:
    """(container name, mount source) of every mount of every running container, and why docker
    could not be asked ("" when it answered)."""
    try:
        ps = _docker("ps", "-q", "--no-trunc")
        if ps.returncode != 0:
            why = (ps.stderr.strip().splitlines() or ["docker ps failed"])[0]
            return [], f"docker ps failed ({why})"
        ids = ps.stdout.split()
        if not ids:
            return [], ""
        ins = _docker("inspect", *ids)
    except FileNotFoundError:
        return [], "docker is not installed here"
    except _DOCKER_ERRORS as e:
        return [], f"docker did not answer ({e})"
    try:
        data = json.loads(ins.stdout or "null")
    except ValueError:
        data = None
    if not isinstance(data, list) or (ins.returncode != 0 and not data):
        why = (ins.stderr.strip().splitlines() or ["no answer"])[0]
        return [], f"docker inspect failed ({why})"
    found: list[tuple[str, str]] = []
    for c in data:
        if not isinstance(c, dict):
            continue
        name = str(c.get("Name") or c.get("Id") or "?").lstrip("/")
        for m in c.get("Mounts") or []:
            src = m.get("Source") if isinstance(m, dict) else None
            if isinstance(src, str) and src.startswith("/"):
                found.append((name, src))
    return found, ""


def mounting(path: Path, mounts: list[tuple[str, str]]) -> list[str]:
    """The containers whose mount source is `path` or a path inside it, compared part by part (a
    mount of `AB-29` is not one of `AB-293`), as typed and with links resolved."""
    forms = {Path(os.path.abspath(path)), Path(os.path.realpath(path))}
    hits: set[str] = set()
    for name, src in mounts:
        for s in {Path(src), Path(os.path.realpath(src))}:
            if any(s == f or f in s.parents for f in forms):
                hits.add(name)
    return sorted(hits)


def remove_worktree(main: Path, path: Path, links: list[Path]) -> str:
    """Remove the worktree at `path` once every check passed: the `.git` file of each submodule in
    it and the worktree's own submodule clones first (git refuses a worktree holding either), then
    a plain `git worktree remove`. "" when it is gone, else why not."""
    gitdir = out(path, "rev-parse", "--absolute-git-dir")
    common = out(main, "rev-parse", "--path-format=absolute", "--git-common-dir")
    if not gitdir or not common:
        return "git cannot find its git dir"
    if Path(gitdir).resolve().parent != (Path(common) / "worktrees").resolve():
        return f"its git dir {gitdir} is not one of {common}/worktrees"
    modules = Path(gitdir) / "modules"
    if links or modules.exists() or modules.is_symlink():
        try:
            for link in links:
                link.unlink()
            if modules.is_dir() and not modules.is_symlink():
                shutil.rmtree(modules)
        except OSError as e:
            return (
                f"removing its submodule clones failed: {e}; `git submodule update --init` "
                "in it fetches them again"
            )
    r = run(main, "worktree", "remove", str(path))
    return "" if r.returncode == 0 else f"remove failed: {r.stderr.strip()}"


def merged(main: Path, head: str, base: str) -> bool:
    """Every commit of the branch is on base: the tip is an ancestor of base, or the branch has no
    merge commit and everything it changed is on base as it has it (`patch_landed`: it landed by
    cherry-pick or rebase). A branch holding a merge commit counts only as an ancestor."""
    ref = f"refs/heads/{base}"
    if run(main, "merge-base", "--is-ancestor", head, ref).returncode == 0:
        return True
    return patch_landed(main, head, ref)


def patch_landed(main: Path, head: str, ref: str) -> bool:
    """The branch's work is on `ref` though its commits are not: no commit of `ref..head` is a merge
    or empty, and every entry the branch changed since it forked (a file, a mode, a symlink, a
    submodule pin) is the same object on `ref` as at `head`. Compared by tree entry with plumbing
    (`diff-tree`, `ls-tree`), never by patch id or porcelain diff: a patch id ignores whitespace,
    and a porcelain diff runs the user's external diff driver and honours `.gitmodules`
    `ignore = all`. Any error, or a path git cannot hand back as text, reads as not landed."""
    rng = f"{ref}..{head}"
    try:
        merges = run(main, "rev-list", "--merges", "--count", rng)
        commits = run(main, "rev-list", "--count", rng)
        changing = run(main, "rev-list", "--count", rng, "--", ".")
        fork = out(main, "merge-base", ref, head)
        if (
            merges.returncode != 0
            or merges.stdout.strip() != "0"
            or commits.returncode != 0
            or changing.returncode != 0
            or commits.stdout.strip() in ("", "0")
            or commits.stdout.strip() != changing.stdout.strip()
            or not fork
        ):
            return False  # a merge, an empty commit (nothing on `ref` carries it), or no fork
        touched = run(
            main,
            "diff-tree",
            "-r",
            "-z",
            "--name-only",
            "--no-renames",
            "--ignore-submodules=none",
            fork,
            head,
        )
        paths = [p for p in touched.stdout.split("\0") if p]
        if touched.returncode != 0 or not paths:
            return False
        here = run(main, "ls-tree", "-z", "--full-tree", head, "--", *paths)
        there = run(main, "ls-tree", "-z", "--full-tree", ref, "--", *paths)
    except UnicodeDecodeError:
        return False
    return (
        here.returncode == 0 and there.returncode == 0 and here.stdout == there.stdout
    )


def held_elsewhere(main: Path, head: str, branch: str) -> bool:
    """Another local branch holds the tip: a worktree with no commits of its own, made from a commit of
    another issue's branch, holds nothing that removing it loses."""
    refs = out(
        main, "for-each-ref", "--contains", head, "--format=%(refname)", "refs/heads/"
    )
    return any(r != f"refs/heads/{branch}" for r in refs.splitlines())


def delete_branch(main: Path, branch: str, head: str) -> str:
    """Delete the pruned worktree's branch, only while it still points at the tip judged landed
    (`update-ref -d <ref> <old>` is git's compare-and-delete). Its error, or ""."""
    r = run(main, "update-ref", "-d", f"refs/heads/{branch}", head)
    return "" if r.returncode == 0 else r.stderr.strip()


def mid_operation(path: Path) -> str:
    """A rebase, merge, cherry-pick, revert or bisect in progress: its state lives in the worktree's
    git dir and goes with it."""
    gitdir = Path(out(path, "rev-parse", "--absolute-git-dir") or path / ".git")
    for name in (
        "rebase-merge",
        "rebase-apply",
        "MERGE_HEAD",
        "CHERRY_PICK_HEAD",
        "REVERT_HEAD",
        "BISECT_LOG",
    ):
        if (gitdir / name).exists():
            return name
    return ""


# How long a fresh worktree is kept with no session tied to it. `EnterWorktree` adds the worktree,
# copies settings into it and only then locks it, so a worktree being created is briefly empty,
# clean, merged and unheld.
FRESH_GRACE_SECONDS = 600


def committed_since_created(main: Path, branch: str) -> bool:
    """The branch has moved since it was created. A fresh worktree is clean and trivially merged; it
    holds nothing, so it is pruned only once it is past `FRESH_GRACE_SECONDS` and no running claude
    is tied to it, the caller's own session included (Claude Code runs subagents in its own process,
    so a sibling subagent's worktree reads as the caller's)."""
    return (
        len(
            out(
                main, "reflog", "show", "--format=%H", f"refs/heads/{branch}"
            ).splitlines()
        )
        > 1
    )


def created_at(main: Path, path: Path, branch: str) -> float:
    """When the worktree at `path` came to be: the later of its branch's creation (the oldest reflog
    entry's own date, not its commit's) and the worktree's own addition (`git worktree add` writes
    its `commondir` once), so a worktree just added on an old branch is new. Now when git cannot
    say."""
    entries = out(
        main, "reflog", "show", "--date=unix", "--format=%gd", f"refs/heads/{branch}"
    ).split()
    m = re.search(r"@\{(\d+)\}$", entries[-1]) if entries else None
    gitdir = out(path, "rev-parse", "--absolute-git-dir")
    try:
        added = (Path(gitdir) / "commondir").stat().st_mtime if gitdir else None
    except OSError:
        added = None
    if not m or added is None:
        return time.time()
    return max(float(m.group(1)), added)


def adopt_steps(path: Path) -> str:
    """How the calling session takes over the worktree, and what the dead session left to read."""
    steps = (
        f"`python3 .claude/hooks/worktree.py adopt {path.name}`, then `EnterWorktree` "
        f"path={path}, then read the issue's last LuxPM note"
    )
    t = last_session(path)
    if t is None:
        return steps + "."
    steps += f", the end of the transcript {t}"
    pad = scratchpad(t.stem)
    if pad is not None:
        steps += f" and the scratchpad {pad}"
    return f"{steps}. The owner's fallback: cd {path} && claude --resume {t.stem}."


def cmd_adopt(key: str) -> int:
    """Claim a worktree whose session is gone for the calling session: the worktree's git lock,
    written with this session's `pid N start T`. Creating the lock file is atomic (O_EXCL), and a
    stale lock is moved aside by one rename and checked to be the lock judged, so of two sessions
    adopting at once exactly one gets it."""
    main = main_checkout(Path.cwd())
    if main is None:
        print("not inside a git checkout with a .git directory", file=sys.stderr)
        return 2
    path = main / ".claude" / "worktrees" / key
    row = next(
        (w for w in worktrees(main) if Path(w.get("worktree", "")) == path), None
    )
    if row is None:
        print(f"REFUSING: no worktree at {path}", file=sys.stderr)
        return 2
    if not process_table():
        print(f"REFUSING: {UNKNOWN_SESSION}.", file=sys.stderr)
        return 2
    mine = me()
    if mine is None:
        print(
            "REFUSING: adopt claims a worktree for a claude session, and none runs this",
            file=sys.stderr,
        )
        return 2
    judged = row.get("locked")
    live, own, session = session_state(path, judged, mine[0])
    if live:
        print(f"REFUSING: {key} is not yours to adopt: {session}", file=sys.stderr)
        return 1
    if own and judged is not None and lock_holder(judged)[0] == mine[0]:
        print(f"{key} is already this session's. {adopt_steps(path)}")
        return 0
    taken = f"REFUSING: another session took {key} first"
    gitdir = Path(out(path, "rev-parse", "--absolute-git-dir"))
    lock = gitdir / "locked"
    if lock.exists():
        aside = gitdir / f"locked.adopt-{mine[0]}"
        try:
            os.rename(lock, aside)
        except FileNotFoundError:
            print(taken, file=sys.stderr)
            return 1
        held = aside.read_text(encoding="utf-8", errors="replace").strip()
        if held != (judged or "").strip() and not (judged == "1" and not held):
            with contextlib.suppress(FileExistsError):
                os.link(aside, lock)  # not the lock judged: put it back
            os.unlink(aside)
            print(taken, file=sys.stderr)
            return 1
        os.unlink(aside)
    try:
        fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
    except FileExistsError:
        print(taken, file=sys.stderr)
        return 1
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        f.write(f"claude session adopted {key} (pid {mine[0]} start {mine[1]})")
    print(f"Adopted {key}: {session}. {adopt_steps(path)}")
    return 0


WORKTREE_NAME = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$")


def cmd_add(key: str) -> int:
    """Create `.claude/worktrees/<KEY>` on `worktree-<KEY>` from the newest base (origin's when there
    is one), and record the calling session in it as `EnterWorktree` does. A subagent the session
    starts works there by absolute path while the session stays in the main checkout: between its
    commands no process sits in the worktree, so without the record another session's `list` would
    read a running agent's worktree as dead, offer it as ADOPT, or prune it."""
    main = main_checkout(Path.cwd())
    if main is None:
        print("not inside a git checkout with a .git directory", file=sys.stderr)
        return 2
    if not WORKTREE_NAME.match(key):
        print(
            f"REFUSING: {key!r} is not a worktree name (letters, digits, . _ -)",
            file=sys.stderr,
        )
        return 2
    if me() is None:
        print(
            "REFUSING: add records the claude session it is run from, and none runs this",
            file=sys.stderr,
        )
        return 2
    base = base_branch(main)
    # the newer of the local base and origin's: origin's only when the local base is behind it
    remote = f"refs/remotes/origin/{base}"
    start = base
    if (
        out(main, "rev-parse", "--verify", "--quiet", remote)
        and run(main, "merge-base", "--is-ancestor", base, remote).returncode == 0
    ):
        start = remote
    path = main / ".claude" / "worktrees" / key
    r = run(main, "worktree", "add", str(path), "-b", f"worktree-{key}", start)
    if r.returncode != 0:
        print(f"REFUSING: git worktree add failed: {r.stderr.strip()}", file=sys.stderr)
        return 1
    if not record_session(path, (ENTERED, ADDED)):
        print(
            f"WARNING: {path} was added, but this session could not be recorded in it: another "
            "session's `list` may read it as having none",
            file=sys.stderr,
        )
        return 1
    print(
        f"Added {path} on worktree-{key} from {start}, recorded as this session's. Work in it by "
        "absolute path, keep the session in the main checkout while its agents run, and land with "
        f"`cd {path} && python3 .claude/hooks/worktree.py land`."
    )
    return 0


def cmd_list(prune: bool) -> int:
    here = Path.cwd()
    main = main_checkout(here)
    if main is None:
        print(
            "not inside a git checkout with a .git directory; nothing to list",
            file=sys.stderr,
        )
        return 2
    base = base_branch(main)
    if not out(main, "rev-parse", "--verify", "--quiet", f"refs/heads/{base}"):
        print(
            f"no local branch {base!r} (the default branch) to judge worktrees against",
            file=sys.stderr,
        )
        return 2
    agents_dir = main / ".claude" / "worktrees"
    if prune:
        run(
            main, "worktree", "prune"
        )  # metadata of worktrees whose directory is already gone
    current = out(here, "rev-parse", "--show-toplevel")
    caller = (me() or ("", ""))[0]
    kept: list[str] = []
    adopt: list[Path] = []
    to_land: list[tuple[Path, int]] = []
    others = 0
    owed = 0
    removed = 0
    docker: tuple[list[tuple[str, str]], str] | None = (
        None  # asked once, when a removal is near
    )
    for wt in worktrees(main):
        path = Path(wt.get("worktree", ""))
        if path == main or not path.is_dir():
            continue
        branch = wt.get("branch", "").replace("refs/heads/", "")
        head = wt.get("HEAD", "")
        name = path.name
        issue = name if ISSUE.match(name) else "(no issue key)"
        age = int(out(path, "log", "-1", "--format=%ct") or "0")
        days = int((time.time() - age) / 86400) if age else -1
        is_dirty = dirty(path, main)
        is_merged = bool(head) and merged(main, head, base)
        # Only an agent's worktree, on the branch Claude Code made for it, is ever pruned. Anything
        # else (the owner's own worktree, a detached one) is listed, never removed: its ref and its
        # files are the owner's.
        agent_owned = path.parent == agents_dir and branch == f"worktree-{name}"
        # A subagent's isolation worktree (`Agent isolation: "worktree"`) is locked with its parent
        # session's pid for as long as that session runs; once Claude Code records the subagent
        # finished, that lock holds nothing (a process still working in it, or another session's
        # entry, still does).
        finished = agent_owned and harness_agent_finished(path)
        lock = wt.get("locked")
        if finished and lock is not None and lock.startswith(HARNESS_LOCK):
            lock = None
        live, own, session = session_state(path, lock, caller)
        busy = mid_operation(path)
        fresh = agent_owned and not committed_since_created(main, branch)
        # this session made it with `add` for a subagent: its agent works there until its `land`
        # clears that record, whatever of its work already reached the base
        recorded = bool(caller) and caller in entered_by(path, ADDED)
        # a subagent's isolation worktree this session's own harness lock names: its agent may still
        # run there (in this process) until Claude Code records it finished
        lock_is_callers = (
            lock is not None
            and lock.startswith(HARNESS_LOCK)
            and bool(caller)
            and lock_holder(lock) == (caller, True)
        )
        landed = is_merged or (
            fresh and bool(head) and held_elsewhere(main, head, branch)
        )
        state = ", ".join(
            s
            for s in (
                "has files git does not hold" if is_dirty else "clean",
                f"merged into {base}"
                if is_merged
                else "its commit is on another branch"
                if landed
                else f"NOT merged into {base}",
                session,
                "its agent finished" if finished else "",
                f"{busy} in progress" if busy else "",
                "no commits yet" if fresh else "",
                "" if agent_owned else "not an agent worktree (never pruned)",
                f"last commit {days}d ago" if days >= 0 else "",
            )
            if s
        )
        line = f"{issue:<16} {branch or '(detached)':<36} {state}  {path}"
        safe = (
            agent_owned
            and not is_dirty
            and landed
            and not live
            and not ((recorded or lock_is_callers) and not finished)
            and not busy
            and str(path) != current
            # a process working inside it is using it: the caller's own claude (Claude Code runs
            # subagents in its own process), the owner's shell, a server an agent left running
            # with none, or one that left a process out, nobody can be seen working inside it
            and complete_table()
            and not working_in(path)
            and not (
                fresh
                and not finished
                and (
                    own
                    or time.time() - created_at(main, path, branch)
                    < FRESH_GRACE_SECONDS
                )
            )
        )
        held = ""
        links: list[Path] = []
        if prune and safe:
            if docker is None:
                docker = running_mounts()
                if docker[1]:
                    print(
                        f"no running container checked: {docker[1]}. A stack running from a "
                        "pruned worktree loses its bind mounts; deploy from the main checkout."
                    )
            users = mounting(path, docker[0])
            if users:
                held = (
                    f"a running container mounts it ({', '.join(users)}): redeploy that stack "
                    "from the main checkout, then prune"
                )
            else:
                held, links = submodule_hold(path, main)
        if prune and safe and not held:
            if "locked" in wt:  # its holder is gone, or is the caller
                run(main, "worktree", "unlock", str(path))
            failed = remove_worktree(main, path, links)
            if not failed:
                kept_branch = delete_branch(main, branch, head)
                removed += 1
                print(f"pruned   {line}")
                if kept_branch:
                    print(f"  branch {branch} kept: {kept_branch}")
                continue
            line += f"  ({failed})"
        elif held:
            line += f"  (kept: {held})"
        kept.append(line)
        owes = is_dirty or not landed
        owed += owes
        if owes and finished and not is_dirty and not live and str(path) != current:
            # a finished subagent's commits: landing them is the one step, whoever runs it
            to_land.append((path, count(main, f"refs/heads/{base}..{head}")))
        elif owes and agent_owned and not live and not own and str(path) != current:
            adopt.append(path)
        elif owes and not own and str(path) != current:
            others += 1
    for line in kept:
        print(f"kept     {line}")
    for path, n in to_land:
        print(
            f"LAND     {path.name}: its agent finished with {n} commit(s) not on {base}. "
            f"`cd {path} && python3 .claude/hooks/worktree.py land` lands them (a commit {base} "
            "already has drops out in the rebase); the next `list --prune` removes it."
        )
    for path in adopt:
        print(f"ADOPT    {path.name}: its session is gone. {adopt_steps(path)}")
    print(
        f"{removed} pruned, {len(kept)} kept, {owed} holding unmerged or uncommitted work, "
        f"{len(adopt)} with no live session to adopt"
    )
    if adopt:
        print(
            "An ADOPT worktree is yours, ahead of any new work: run its steps, and never start its "
            "issue afresh beside it."
        )
    if others:
        print(
            "A worktree with a live session, or that is not an agent's, is not yours: name it to the "
            "owner in one line. Never remove one with --force or discard_changes on your own."
        )
    return 0


def cmd_land() -> int:
    here = Path(out(Path.cwd(), "rev-parse", "--show-toplevel") or Path.cwd())
    main = main_checkout(here)
    if main is None:
        print("not inside a git checkout with a .git directory", file=sys.stderr)
        return 2
    if here == main:
        print(
            "REFUSING: land runs inside the issue's worktree, not the main checkout. "
            "Enter it first (EnterWorktree path=.claude/worktrees/<ISSUE-KEY>).",
            file=sys.stderr,
        )
        return 2
    branch = out(here, "symbolic-ref", "--quiet", "--short", "HEAD")
    base = base_branch(main)
    if not branch:
        print("REFUSING: the worktree must be on its issue's branch", file=sys.stderr)
        return 2
    if checked_out(main) != base:
        print(
            f"REFUSING: the main checkout ({main}) is not on {base}, the default branch, so a "
            "fast-forward would land this issue somewhere else. It is the owner's checkout: tell the "
            f"owner, and land once it is back on {base}.",
            file=sys.stderr,
        )
        return 1
    # v3: an exact copy of the main checkout's ignored file is not work (Claude Code copies its
    # settings.local.json into every worktree it creates)
    held = blockers(here, main)
    if held:
        shown = "".join(f"  {line}\n" for line in held[:20])
        more = f"  ... and {len(held) - 20} more\n" if len(held) > 20 else ""
        print(
            f"REFUSING: {here} has uncommitted changes: commit them (or remove what is not yours to ship), then land.\n"
            f"{shown}{more}"
            "An ignored file a build regenerates (a built asset, a stamp) is removed with a plain `rm <file>`; "
            "a tool's cache directory never blocks.",
            file=sys.stderr,
        )
        return 1
    if out(main, "status", "--porcelain", "--untracked-files=no"):
        print(
            f"REFUSING: the main checkout ({main}) has uncommitted changes to tracked files. It is the "
            "owner's checkout: tell the owner, and land once it is clean.",
            file=sys.stderr,
        )
        return 1
    local = f"refs/heads/{base}"
    remote = f"refs/remotes/origin/{base}"
    # `[agents] push = "agent"`: land against origin, not only this machine. An agent elsewhere may
    # have pushed since this worktree branched, so the local base first takes origin's.
    pushing = push_mode(main) == "agent" and bool(
        out(main, "remote", "get-url", "origin")
    )
    try:
        hold = (main / ".claude" / ".push-hold").read_text(encoding="utf-8").strip()
    except OSError:
        hold = ""
    if pushing and hold:
        # a recorded hold (unpushed-stop-guard's): nothing is pushed while it stands
        print(f"Push held (.claude/.push-hold): {hold}. Landing locally only.")
        pushing = False
    if pushing:
        refused = sync_with_origin(main, base)
        if refused:
            print(refused, file=sys.stderr)
            return 1
    new = count(here, f"HEAD..{local}")
    if new:
        r = run(here, "rebase", local)
        if r.returncode != 0:
            run(here, "rebase", "--abort")
            print(
                f"REFUSING: rebasing {branch} onto {base} conflicts; nothing changed. Resolve it here "
                f"(`git rebase {base}`, fix, `git rebase --continue`), re-run the gate, then land.\n"
                + (r.stdout + r.stderr).strip(),
                file=sys.stderr,
            )
            return 1
        print(
            f"Rebased {branch} onto {new} new commit(s) from {base}. What you tested is not what would "
            "land: re-run the touched tests and the gate here, then run land again.",
            file=sys.stderr,
        )
        return 1
    ahead = count(here, f"{local}..HEAD")
    issue_commits = out(here, "rev-list", "--reverse", f"{local}..HEAD").split()
    # A path the issue adds that already exists, untracked or ignored, in the owner's checkout: git
    # treats an ignored file as expendable and the fast-forward overwrites it (an owner's `.env`).
    held = held_files(main, added_paths(here, f"{local}...HEAD"))
    if held:
        print(
            f"REFUSING: this issue adds {', '.join(held[:5])}, which already exist in the owner's "
            "checkout as files git does not hold; landing would overwrite them. Tell the owner.",
            file=sys.stderr,
        )
        return 1
    # what origin lacks: the issue's commits, and landed commits the local base holds unpushed
    unpushed = 0
    if pushing:
        known = out(main, "rev-parse", "--verify", "--quiet", remote)
        unpushed = count(here, f"{remote}..HEAD") if known else 1
    if not ahead and not unpushed:
        print(f"Nothing to land: {branch} has no commits that {base} lacks.")
        return 0
    if pushing:
        # the push is the compare-and-swap: origin takes it only as a fast-forward of what it holds
        was = out(main, "rev-parse", "--verify", "--quiet", remote)
        r = run_net(here, "push", "--quiet", "origin", f"HEAD:{local}", push=True)
        if r.returncode == 124:
            # timed out: origin may still have taken it, so ask where its base is now
            now = run_net(main, "ls-remote", "--heads", "origin", local)
            head = out(here, "rev-parse", "HEAD")
            tip = now.stdout.split()[:1] if now.returncode == 0 else None
            if tip == [head]:
                r = subprocess.CompletedProcess(r.args, 0, "", "")
            elif tip == ([was] if was else []):
                # origin's own side may still take a push it already received, so this is what
                # origin held when asked, never a proof that the push will not land
                print(
                    f"REFUSING: the push of {branch} to {base} ran past {net_limit(True):g}s, and "
                    f"origin had not taken it when asked (it held {(was or 'no ' + base)[:8]}). The "
                    "push runs this repo's pre-push hook: if that needs longer, set "
                    "LUXARCH_LAND_PUSH_TIMEOUT=<seconds>. Run land again: it fetches origin, and "
                    "finishes or pushes again.\n" + (r.stdout + r.stderr).strip(),
                    file=sys.stderr,
                )
                return 1
            else:
                print(
                    f"REFUSING: the push of {branch} to {base} timed out, and origin's base could "
                    "not be confirmed; it may have landed there. Run land again: it fetches origin "
                    "and finishes, or reports nothing to land.\n"
                    + (r.stdout + r.stderr).strip(),
                    file=sys.stderr,
                )
                return 1
        if r.returncode != 0:
            print(
                f"REFUSING: origin rejected the push of {branch} to {base}; nothing landed. If origin "
                "moved again, run land again: it fetches, rebases and stops for the gate. Never "
                f"`git pull --rebase` on {base}.\n" + (r.stdout + r.stderr).strip(),
                file=sys.stderr,
            )
            return 1
    if ahead:
        # only ever a fast-forward: it cannot drop a commit the base gained meanwhile (the owner's,
        # or another agent's landing); then it fails, and nothing on the base moves
        r = run(main, "merge", "--ff-only", "--quiet", branch)
        if r.returncode != 0:
            print(
                f"REFUSING: {base} moved while landing, so it cannot fast-forward to {branch}"
                + (
                    "; origin already holds the push. Run land again: it brings the local base up."
                    if pushing
                    else "; nothing changed. Run land again."
                )
                + f"\n{(r.stdout + r.stderr).strip()}",
                file=sys.stderr,
            )
            return 1
    short = out(main, "rev-parse", "--short", base)
    if pushing:
        print(
            f"Landed and pushed {max(ahead, unpushed)} commit(s) on {base} at {short}."
        )
        then = ""
    else:
        print(f"Landed {ahead} commit(s) on {base} at {short}.")
        then = f" Then push {base} as this repo's [agents] push declares."
    # the agent working here is done: its session's record no longer holds the worktree
    clear_session(here)
    if issue_commits:
        print(
            "Landed commits, one JSON object per line: the close-out's "
            "`luxpm_log_activity(commits=[...])` takes each verbatim."
        )
        for sha in issue_commits:
            print(json.dumps(commit_record(main, sha)))
    users = mounting(here, running_mounts()[0])
    if users:
        print(
            f"WARNING: running container(s) {', '.join(users)} mount files in this worktree. "
            "`list --prune` keeps it while they run: deploy that stack from the main checkout "
            f"({main}), then prune."
        )
    # ExitWorktree's `remove` judges the branch against the commit it was made from, so it refuses
    # every landed branch as unmerged; `list --prune` judges it against the base and removes it.
    print(
        f"Now remove the worktree: ExitWorktree action=keep, then from the main checkout "
        f"`python3 .claude/hooks/worktree.py list --prune` (it prunes {branch}: landed and "
        f"clean). Never ExitWorktree remove with discard_changes.{then}"
    )
    return 0


# The files listed per landed commit; a commit touching more says so (`files_truncated`).
MAX_FILES = 200


def commit_record(main: Path, sha: str) -> dict[str, object]:
    """A landed commit as the tracker's commit link takes it: its sha, `committed_at` from git
    (`%cI`, never typed), and the files it touched (`--name-status -M`: a rename as its new path,
    with the old one beside it)."""
    files: list[dict[str, str]] = []
    raw = out(
        main,
        "diff-tree",
        "--root",
        "--no-commit-id",
        "-r",
        "-M",
        "--name-status",
        "-z",
        sha,
    ).split("\0")
    i = 0
    total = 0
    while i < len(raw) and raw[i]:
        status = raw[i]
        renamed = status[:1] in ("R", "C")
        paths = raw[i + 1 : i + (3 if renamed else 2)]
        i += 3 if renamed else 2
        if not paths:
            break
        total += 1
        if len(files) < MAX_FILES:
            entry = {"status": status[:1], "path": paths[-1]}
            if renamed and len(paths) == 2:
                entry["from"] = paths[0]
            files.append(entry)
    return {
        "sha": sha,
        "committed_at": out(main, "show", "-s", "--format=%cI", sha),
        "files": files,
        "files_truncated": total > len(files),
    }


def added_paths(cwd: Path, spec: str) -> str:
    """Every path `spec` adds, a rename's new name included (`--no-renames` lists it as added)."""
    return out(cwd, "diff", "--name-only", "--no-renames", "--diff-filter=A", spec)


def held_files(main: Path, paths: str) -> list[str]:
    """The paths that exist in the owner's checkout as files git does not hold (an ignored `.env`),
    or that sit under such a file (`cfg/app.toml` where `cfg` is one): a fast-forward that adds them
    overwrites or deletes the owner's file."""
    held: list[str] = []
    for f in paths.splitlines():
        if not f:
            continue
        p = Path(f)
        for q in [p, *(a for a in p.parents if str(a) != ".")]:
            on_disk = main / q
            exists = on_disk.exists() or on_disk.is_symlink()
            if q != p and on_disk.is_dir() and not on_disk.is_symlink():
                continue  # a directory above the path is no file of the owner's
            if (
                exists
                and run(main, "ls-files", "--error-unmatch", str(q)).returncode != 0
            ):
                held.append(str(q))
                break
    return held


def sync_with_origin(main: Path, base: str) -> str:
    """Bring the local base up to origin's before landing, or say why not ("" when done). It only
    ever fast-forwards. Origin rewritten (its previous tip no longer in it) or a local base holding
    commits origin lacks while origin also moved are the owner's to reconcile: landing on either
    would push back what origin removed, or rebase landed history."""
    local = f"refs/heads/{base}"
    remote = f"refs/remotes/origin/{base}"
    before = out(main, "rev-parse", "--verify", "--quiet", remote)
    heads = run_net(main, "ls-remote", "--heads", "origin", local)
    if heads.returncode != 0:
        return (
            f"REFUSING: cannot reach origin/{base}, so landing here could not be pushed and would "
            "race the agents that can. Nothing changed. Land once origin is reachable.\n"
            + (heads.stdout + heads.stderr).strip()
        )
    if not heads.stdout.strip():
        if before:
            return (
                f"REFUSING: origin no longer has {base} (it had {before[:8]}). Nothing changed. "
                "Tell the owner."
            )
        return ""  # origin has no base yet: the push creates it
    # fetched beside the tracking ref, which moves only when origin's base still holds its previous
    # tip: a rewrite stays visible to every later land until the owner reconciles it
    # one scratch ref per land, so two lands on this machine never read each other's fetch
    fetched = f"refs/luxarch-land/{os.getpid()}-{time.time_ns()}/{base}"
    # `--refmap=`: without it git also moves the configured tracking ref on any fetch of the branch
    f = run_net(main, "fetch", "--quiet", "--refmap=", "origin", f"+{local}:{fetched}")
    tip = out(main, "rev-parse", "--verify", "--quiet", fetched)
    run(main, "update-ref", "-d", fetched)
    if f.returncode != 0 or not tip:
        return (
            f"REFUSING: cannot fetch origin/{base}. Nothing changed. Land once origin is reachable.\n"
            + (f.stdout + f.stderr).strip()
        )
    rewritten = False
    if before:
        a = run(main, "merge-base", "--is-ancestor", before, tip)
        if a.returncode not in (0, 1):
            return (
                f"REFUSING: cannot compare origin/{base} with its previous tip {before[:8]}; nothing "
                f"changed.\n{(a.stdout + a.stderr).strip()}"
            )
        rewritten = a.returncode == 1
    # moved only from the value it was read at: another land that moved it meanwhile wins, and this
    # one reads the tracking ref again below
    if not rewritten:
        run(main, "update-ref", remote, tip, *([before] if before else []))
    if rewritten:
        return (
            f"REFUSING: origin/{base} was rewritten: its previous tip {before[:8]} is no longer in "
            "it (a force-push). Landing could push back what was removed. Nothing changed. Tell "
            "the owner."
        )
    behind = count(main, f"{local}..{remote}")
    mine = count(main, f"{remote}..{local}")
    if behind and mine:
        return (
            f"REFUSING: the local {base} and origin/{base} diverged: {mine} commit(s) here are not "
            f"on origin and {behind} on origin are not here. Reconciling them is the owner's call; "
            f"nothing changed. Tell the owner, and do not rebase or reset {base}."
        )
    if behind:
        held = held_files(main, added_paths(main, f"{local}...{remote}"))
        if held:
            return (
                f"REFUSING: origin/{base} adds {', '.join(held[:5])}, which exist in the owner's "
                "checkout as files git does not hold; fast-forwarding would overwrite them. Tell "
                "the owner."
            )
        r = run(main, "merge", "--ff-only", "--quiet", remote)
        if r.returncode != 0:
            return (
                f"REFUSING: fast-forward of {base} to origin/{base} failed; nothing changed.\n"
                + (r.stdout + r.stderr).strip()
            )
    return ""


def read_event(seconds: float = 2.0) -> str:
    """The hook event on stdin, read until it ends, but for at most `seconds`: Claude Code closes
    stdin after the event, and a bare run from a script whose stdin stays open must not hang."""
    fd = sys.stdin.fileno()
    deadline = time.monotonic() + seconds
    chunks: list[bytes] = []
    while True:
        left = deadline - time.monotonic()
        if left <= 0 or not select.select([fd], [], [], left)[0]:
            break
        chunk = os.read(fd, 65536)
        if not chunk:
            break
        chunks.append(chunk)
    return b"".join(chunks).decode("utf-8", "replace")


def main_cli(argv: list[str]) -> int:
    main = main_checkout(Path.cwd())
    if main is not None and restore_hookspath(main):
        print(
            "core.hooksPath was an absolute path to this repo's hooks/: set back to `hooks`"
        )
    for link in link_site_config(main) if main is not None else []:
        print(f"linked the main checkout's {SITE_CONFIG} into {link}")
    if argv[:1] == ["restore-hookspath"]:
        return 0
    if not argv and not sys.stdin.isatty():
        # the PostToolUse hook: Claude Code runs it with the event on stdin, no arguments
        if main is not None:
            record_entry(main, read_event())
        return 0
    if argv[:1] == ["list"]:
        return cmd_list("--prune" in argv[1:])
    if argv[:1] == ["land"]:
        return cmd_land()
    if argv[:1] == ["adopt"] and len(argv) == 2:
        return cmd_adopt(argv[1])
    if argv[:1] == ["add"] and len(argv) == 2:
        return cmd_add(argv[1])
    print(__doc__, file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main_cli(sys.argv[1:]))
